"use client";
import { useMorph } from "@/lib/sahajiv-motion/use-morph";
import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Icon } from "@/components/ui/icon";
import { useFlowGroup } from "@/lib/sahajiv-motion/use-flow";
const SidebarContext = React.createContext<{
  open: boolean;
  setOpen: (open: boolean) => void;
} | null>(null);
export function useSidebar() {
  const context = React.useContext(SidebarContext);
  if (!context)
    throw new Error("Sidebar parts must be inside Sidebar or SidebarProvider");
  return context;
}
export type SidebarProviderProps = {
  children: React.ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
};
export function SidebarProvider({
  children,
  open,
  defaultOpen = true,
  onOpenChange,
}: SidebarProviderProps) {
  const [local, setLocal] = React.useState(defaultOpen);
  return (
    <SidebarContext.Provider
      value={{
        open: open ?? local,
        setOpen: (next) => {
          if (open === undefined) setLocal(next);
          onOpenChange?.(next);
        },
      }}
    >
      {children}
    </SidebarContext.Provider>
  );
}
export const sidebarVariants = cva(
  "v-sidebar relative self-stretch flex shrink-0 flex-col gap-[var(--s-2)] w-[var(--sidebar-w)] min-h-0 max-h-none bg-[var(--v-structure)] text-[color:var(--on-structure)] rounded-[var(--r-panel)] pt-[var(--s-6)] px-[var(--s-4)] pb-[var(--s-5)]",
);
export type SidebarProps = React.ComponentProps<"aside"> & {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Container layout fills its parent; viewport layout follows the authored standalone rail. */
  layout?: "container" | "viewport";
};
export function Sidebar({
  open,
  defaultOpen = true,
  onOpenChange,
  layout = "container",
  ...props
}: SidebarProps) {
  const parent = React.useContext(SidebarContext);
  return parent && open === undefined && onOpenChange === undefined ? (
    <SidebarRail data-layout={layout} {...props} />
  ) : (
    <SidebarProvider
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      <SidebarRail data-layout={layout} {...props} />
    </SidebarProvider>
  );
}
function SidebarRail({ref: externalMorphRef,  className, ...props }: React.ComponentProps<"aside">) {
  const sidebar = useSidebar();
  const ownedMorphRef = useMorph<HTMLElement>("surfaces", externalMorphRef);
  return (
    <aside ref={ownedMorphRef}
      data-slot="sidebar"
      data-part="root"
      data-state={sidebar.open ? "expanded" : "collapsed"}
      className={cn(
        sidebarVariants(),
        !sidebar.open && "-mini w-[var(--sidebar-w-mini)]",
        className,
      )}
      {...props}
    />
  );
}
export type SidebarHeaderProps = React.ComponentProps<"div">;
export function SidebarHeader({ className, ...props }: SidebarHeaderProps) {
  return (
    <div
      data-slot="sidebar-header"
      data-part="header"
      className={cn(
        "v-brand relative flex items-center justify-center gap-[8px] h-[56px] mb-[var(--s-6)] font-[family-name:var(--font-display)] text-[30px] font-medium tracking-[-.02em] text-[color:var(--sidebar-foreground)]",
        className,
      )}
      {...props}
    />
  );
}
export type SidebarTriggerProps = React.ComponentProps<"button">;
export function SidebarTrigger({ref: externalMorphRef, 
  className,
  children,
  onClick,
  ...props
}: SidebarTriggerProps) {
  const sidebar = useSidebar();
  const ownedMorphRef = useMorph<HTMLButtonElement>("icons", externalMorphRef);
  return (
    <button ref={ownedMorphRef}
      data-slot="sidebar-trigger"
      data-part="trigger"
      data-rail-collapse=""
      type="button"
      aria-expanded={sidebar.open}
      aria-label={sidebar.open ? "Collapse the rail" : "Expand the rail"}
      className={cn(
        "v-collapse relative ml-auto shrink-0 grid place-items-center size-[30px] overflow-hidden [border-radius:50%] bg-[var(--v-pink)] text-[color:var(--v-on-accent)] text-[13px] font-[family-name:var(--font-text)] font-medium leading-none tracking-normal",
        className,
      )}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) sidebar.setOpen(!sidebar.open);
      }}
      {...props}
    >
      {children ?? <Icon name="chevron-left" />}
    </button>
  );
}
export type SidebarContentProps = React.ComponentProps<"nav">;
export function SidebarContent({
  ref,
  className,
  ...props
}: SidebarContentProps) {
  const flowRef = useFlowGroup<HTMLElement>(ref);
  return (
    <nav
      ref={flowRef}
      data-slot="sidebar-content"
      data-part="viewport"
      aria-label="Destinations"
      className={cn("v-nav grid gap-[2px]", className)}
      {...props}
    />
  );
}
export type SidebarGroupLabelProps = React.ComponentProps<"div">;
export function SidebarGroupLabel({
  className,
  ...props
}: SidebarGroupLabelProps) {
  return (
    <div
      data-slot="sidebar-group-label"
      className={cn(
        "v-nav__group text-[13px] text-[color:var(--sidebar-muted)] pt-[var(--s-4)] px-[var(--s-3)] pb-[var(--s-2)]",
        className,
      )}
      {...props}
    />
  );
}
export type SidebarMenuButtonProps = React.ComponentProps<"a"> & {
  asChild?: boolean;
  isActive?: boolean;
  label?: string;
};
export function SidebarMenuButton({ref: externalMorphRef, 
  className,
  asChild,
  isActive,
  label,
  ...props
}: SidebarMenuButtonProps) {
  const Comp = asChild ? Slot : "a";
  const accessibleLabel = label ?? getSidebarText(props.children);
  const ownedMorphRef = useMorph<HTMLAnchorElement>("nav", externalMorphRef);
  return (
    <Comp ref={ownedMorphRef}
      data-slot="sidebar-menu-button"
      data-state={isActive ? "active" : "inactive"}
      aria-current={isActive ? "page" : undefined}
      aria-label={accessibleLabel || undefined}
      className={cn(
        "v-nav__item relative flex items-center gap-[var(--s-4)] h-[var(--nav-row)] pl-[var(--s-5)] pr-[var(--s-3)] rounded-[var(--r-md)] text-[color:var(--sidebar-foreground)] text-[length:var(--fs-body)] no-underline",
        className,
      )}
      {...props}
    />
  );
}
export type SidebarMenuLabelProps = React.ComponentProps<"span">;
export function SidebarMenuLabel({
  className,
  ...props
}: SidebarMenuLabelProps) {
  return (
    <span
      data-slot="sidebar-menu-label"
      className={cn(
        "v-nav__label flex-1 min-w-0 overflow-hidden text-ellipsis whitespace-nowrap",
        className,
      )}
      {...props}
    />
  );
}
export type SidebarFooterProps = React.ComponentProps<"div">;
export function SidebarFooter({ className, ...props }: SidebarFooterProps) {
  return (
    <div
      data-slot="sidebar-footer"
      data-part="footer"
      className={cn("v-sidebar__foot mt-auto grid gap-[2px]", className)}
      {...props}
    />
  );
}
export type SidebarMenuBadgeProps = React.ComponentProps<"span">;
export function SidebarMenuBadge({ref: externalMorphRef, 
  className,
  ...props
}: SidebarMenuBadgeProps) {
  const ownedMorphRef = useMorph<HTMLSpanElement>("pills", externalMorphRef);
  return (
    <span ref={ownedMorphRef}
      data-slot="sidebar-menu-badge"
      className={cn(
        "v-nav__count grid place-items-center min-w-[18px] h-[18px] px-[5px] rounded-[var(--r-pill)] bg-[var(--v-pink)] text-[color:var(--v-on-accent)] text-[10px] font-bold",
        className,
      )}
      {...props}
    />
  );
}

function getSidebarText(children: React.ReactNode): string {
  return React.Children.toArray(children)
    .map((child) =>
      typeof child === "string" || typeof child === "number"
        ? String(child)
        : React.isValidElement<{ children?: React.ReactNode }>(child)
          ? getSidebarText(child.props.children)
          : "",
    )
    .filter(Boolean)
    .join(" ");
}

@layer sahajiv-states {
[data-slot="sidebar"] {
  transition: width var(--t-element) var(--enter);
}
[data-slot="sidebar-trigger"] .v-icon {
  width: 12px;
  height: 12px;
  stroke-width: 2.5;
}
[data-slot="sidebar-menu-button"] {
  cursor: pointer;
  transition:
    background var(--t-micro),
    color var(--t-micro);
}
[data-slot="sidebar-menu-button"]:hover {
  background: rgba(251, 244, 230, 0.07);
}
[data-slot="sidebar-menu-button"] .v-icon {
  width: 20px;
  height: 20px;
  transition: transform var(--t-element) var(--enter);
}
[data-slot="sidebar-menu-button"]:hover .v-icon {
  transform: translateY(-1px) rotate(-6deg);
}
[data-slot="sidebar-menu-button"]:active .v-icon {
  transform: scale(0.92);
}
[data-slot="sidebar-menu-button"][aria-current="page"],
[data-slot="sidebar-menu-button"][aria-current="page"] .v-icon {
  color: var(--v-pink);
}
[data-slot="sidebar-menu-button"][aria-current="page"]::after {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--sidebar-primary);
  animation: v-sidebar-breathe var(--breath) ease-in-out infinite;
}
[data-slot="sidebar"].-mini
  :is(.v-nav__label, .v-nav__group, .v-brand span:not(.v-collapse)) {
  display: none;
}
[data-slot="sidebar"].-mini .v-brand {
  justify-content: center;
  font-size: 0;
  min-height: 44px;
  gap: 0;
}
[data-slot="sidebar"].-mini .v-brand > *:not(.v-collapse) {
  display: none;
}
[data-slot="sidebar"].-mini .v-collapse {
  margin: 0;
  width: 36px;
  height: 36px;
  font-size: 13px;
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--v-pink) 28%, transparent);
}
[data-slot="sidebar"].-mini .v-collapse .v-icon {
  width: 15px;
  height: 15px;
  transform: rotate(180deg);
}
[data-slot="sidebar"].-mini .v-nav__item {
  justify-content: center;
  padding: 0;
}
[data-slot="sidebar"].-mini .v-nav__item::after {
  display: none;
}
[data-slot="sidebar"].-mini .v-nav__count {
  position: absolute;
  top: 4px;
  right: 6px;
  min-width: 16px;
  height: 16px;
  font-size: 9px;
}
:root[data-mode="dark"] [data-slot="sidebar"],
:root[data-mode="dark"]
  [data-slot="sidebar"]
  :is(
    .v-nav,
    .v-nav__item,
    .v-nav__label,
    .v-icon,
    .v-sidebar__foot,
    .v-brand
  ) {
  color: var(--structure-text);
}
/* The collapse icon sits on pink, independently of the rail surface. */
:root[data-mode="dark"] [data-slot="sidebar"] [data-slot="sidebar-trigger"] .v-icon {
  color: var(--v-on-accent);
}
:root[data-mode="dark"] [data-slot="sidebar"] .v-nav__item[aria-current="page"],
:root[data-mode="dark"]
  [data-slot="sidebar"]
  .v-nav__item[aria-current="page"]
  :is(.v-nav__label, .v-icon) {
  color: var(--v-pink);
}
:root[data-mode="dark"]
  [data-slot="sidebar"]
  .v-nav__item:hover:not([aria-current="page"]),
:root[data-mode="dark"]
  [data-slot="sidebar"]
  .v-nav__item:hover:not([aria-current="page"])
  :is(.v-nav__label, .v-icon) {
  color: var(--on-structure);
}
@keyframes v-sidebar-breathe {
  0%,
  100% {
    opacity: 0.35;
    transform: scale(0.8);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="sidebar-menu-button"][aria-current="page"]::after {
    animation: none;
  }
}

/* Standalone authored rail; embedded rails keep the container sizing contract. */
[data-slot="sidebar"][data-layout="viewport"] { position: sticky; top: var(--shell-inset); min-height: calc(100vh - var(--shell-inset)*2); max-height: calc(100vh - var(--shell-inset)*2); }

[data-slot="sidebar-content"] { --glide-fg: var(--v-pink); }
[data-slot="sidebar-content"].v-glide > .v-glide__pill { background: rgba(251,244,230,.1); }

[data-slot="sidebar"][data-layout="viewport"]:not(.-mini) { width: auto; }

}
